static char __jcc_std_fenv_h[1038] = "/* fenv.h - floating-point environment declarations for JCC */\n\n#ifndef __FENV_H\n#define __FENV_H\n\ntypedef struct { unsigned long long __opaque[4]; } fenv_t;\ntypedef unsigned int fexcept_t;\n\n#define FE_INVALID 0x01\n#define FE_DIVBYZERO 0x04\n#define FE_OVERFLOW 0x08\n#define FE_UNDERFLOW 0x10\n#define FE_INEXACT 0x20\n#define FE_ALL_EXCEPT (FE_INVALID | FE_DIVBYZERO | FE_OVERFLOW | FE_UNDERFLOW | FE_INEXACT)\n\n#define FE_TONEAREST 0\n#define FE_DOWNWARD 0x400\n#define FE_UPWARD 0x800\n#define FE_TOWARDZERO 0xc00\n\n#define FE_DFL_ENV ((const fenv_t *)-1)\n\nextern int feclearexcept(int excepts);\nextern int fegetexceptflag(fexcept_t *flagp, int excepts);\nextern int feraiseexcept(int excepts);\nextern int fesetexceptflag(const fexcept_t *flagp, int excepts);\nextern int fetestexcept(int excepts);\nextern int fegetround(void);\nextern int fesetround(int round);\nextern int fegetenv(fenv_t *envp);\nextern int feholdexcept(fenv_t *envp);\nextern int fesetenv(const fenv_t *envp);\nextern int feupdateenv(const fenv_t *envp);\n\n#endif /* __FENV_H */\n";
static char __jcc_std_fcntl_h[920] = "/* fcntl.h - core POSIX file-control declarations for JCC */\n\n#ifndef __FCNTL_H\n#define __FCNTL_H\n\n#ifdef _WIN32\n#error \"<fcntl.h> is only available on POSIX targets in JCC\"\n#endif\n\n#include \"unistd.h\"\n\n#define O_RDONLY 0x0000\n#define O_WRONLY 0x0001\n#define O_RDWR 0x0002\n#define O_ACCMODE 0x0003\n\n#ifdef __APPLE__\n#define O_NONBLOCK 0x0004\n#define O_APPEND 0x0008\n#define O_CREAT 0x0200\n#define O_TRUNC 0x0400\n#define O_EXCL 0x0800\n#else\n#define O_CREAT 0100\n#define O_EXCL 0200\n#define O_TRUNC 01000\n#define O_APPEND 02000\n#define O_NONBLOCK 04000\n#endif\n\n#define S_IRUSR 0400\n#define S_IWUSR 0200\n#define S_IXUSR 0100\n#define S_IRGRP 0040\n#define S_IWGRP 0020\n#define S_IXGRP 0010\n#define S_IROTH 0004\n#define S_IWOTH 0002\n#define S_IXOTH 0001\n\nextern int open(const char *path, int oflag, ...);\nextern int creat(const char *path, unsigned int mode);\nextern int fcntl(int fd, int cmd, ...);\n\n#endif /* __FCNTL_H */\n";
static char __jcc_std_dlfcn_h[471] = "/* dlfcn.h - dynamic loading declarations for POSIX JCC targets */\n\n#ifndef __DLFCN_H\n#define __DLFCN_H\n\n#ifdef _WIN32\n#error \"<dlfcn.h> is only available on POSIX targets in JCC\"\n#endif\n\n#define RTLD_LAZY 0x1\n#define RTLD_NOW 0x2\n#define RTLD_LOCAL 0x0\n#define RTLD_GLOBAL 0x100\n\nextern void *dlopen(const char *path, int mode);\nextern void *dlsym(void *handle, const char *symbol);\nextern int dlclose(void *handle);\nextern char *dlerror(void);\n\n#endif /* __DLFCN_H */\n";
static char __jcc_std_complex_h[1018] = "/* complex.h - C99 complex support for JCC */\n\n#ifndef __COMPLEX_H\n#define __COMPLEX_H\n\n#include \"math.h\"\n\n#define complex _Complex\n\n#define __jcc_complex_i __jcc_cmplx(0.0, 1.0)\n#define _Complex_I (__jcc_complex_i)\n#define I _Complex_I\n\n#define CMPLX(x, y) __jcc_cmplx((double)(x), (double)(y))\n#define CMPLXF(x, y) __jcc_cmplxf((float)(x), (float)(y))\n#define CMPLXL(x, y) __jcc_cmplxl((long double)(x), (long double)(y))\n\n#define creal(z) __jcc_creal(z)\n#define crealf(z) __jcc_crealf(z)\n#define creall(z) __jcc_creall(z)\n\n#define cimag(z) __jcc_cimag(z)\n#define cimagf(z) __jcc_cimagf(z)\n#define cimagl(z) __jcc_cimagl(z)\n\n#define conj(z) __jcc_conj(z)\n#define conjf(z) __jcc_conjf(z)\n#define conjl(z) __jcc_conjl(z)\n\n#define cabs(z) hypot(creal(z), cimag(z))\n#define cabsf(z) hypotf(crealf(z), cimagf(z))\n#define cabsl(z) hypotl(creall(z), cimagl(z))\n\n#define carg(z) atan2(cimag(z), creal(z))\n#define cargf(z) atan2f(cimagf(z), crealf(z))\n#define cargl(z) atan2l(cimagl(z), creall(z))\n\n#endif /* __COMPLEX_H */\n";
